history.output:
{
  count: number;
  /** The start of the conversation was reached. */
  done: boolean;
  /** The ts of the page's oldest message, when there was one. */
  oldest?: number;
}

search.input:
{
  limit?: number;
  scope: { kind: "conversation" | "space"; id: string } | { kind: "all" };
  query: NetworkQuery;
  offset?: number;
}

search.output:
{
  /** Native message ids of the hits, in the network's order. Their message facts came before this reply. */
  hits: string[];
  /** How many the network says match in all, when it says. */
  total: null | number;
  /** Pass as `offset` for the next page; null at the end. */
  next: null | number;
  /** The network is still indexing this place (Discord answers 202): ask again after this long. */
  retryAfterMs?: number;
}

mentionables.output:
{
  /** Best first, at most the command's limit. */
  people: MentionablePerson[];
  roles?: MentionableRole[];
  /** You may write */
  everyone?: boolean;
}

threads.output:
{
  count: number;
  /** More after these: ask again with offset + count. */
  more: boolean;
  /** The network is still indexing this channel's threads (Discord's 202): ask the same again after this long. */
  retryAfterMs?: number;
  /** The page's threads, native ids in the network's order (threads.ts ThreadPageView); absent from an older adapter. */
  ids?: string[];
}

reactionContext.output:
{
  canReact: boolean;
  /** Why not, or a limit worth knowing. Shown in the picker. */
  reason?: string;
  /** Only reactions already on the message can be added to (Discord without Add Reactions). */
  existingOnly?: boolean;
  /** Custom emoji usable here: this server first, then others, Matrix image packs. */
  custom: { id: string; name: string; icon?: string; emoji: CustomEmojiFact[] }[];
  /** Absent: this network has no super reactions. */
  super?: { available: boolean; reason?: string };
  /** What this account may do to others' messages here (capability 'moderate'). Absent: nothing. */
  moderation?: MessageModeration;
}

about.output:
{
  /** The network's word for it: "Group", "Server", "Room", "Channel", "Community". */
  noun?: string;
  fields: AboutFields;
  members?: {
    list: AboutMember[];
    /** How many there are; list may hold fewer (Discord servers load members lazily). */
    total?: number;
    complete: boolean;
  };
  /** Adding people here, for an adapter with 'addMembers'. Left out where nobody adds people (DMs, servers, channels). */
  adding?: AboutAdding;
  roles?: AboutRole[];
  rules?: AboutRule[];
  /** This account's own standing here. */
  you?: { role?: string; rank?: number };
  invite?: AboutInvite;
  pinned?: AboutPinned;
  /** Read-only details only some networks have: "Room version", "Verification level", "Created". */
  facts?: { label: string; value: string }[];
  /** Leaving it (capability 'leave', servers.ts). */
  leaving?: AboutLeaving;
  /** Your own nickname here (capability 'nick', the `setNick` command): value null for none. */
  nick?: { value: null | string; canEdit: boolean; reason?: string; max?: number };
  /** You blocked this group: nothing from it reaches you (capability 'block'; the `block` command changes it). */
  blocked?: boolean;
  /** A thread's archiving, locking and following (threads.ts). */
  thread?: AboutThread;
  /** A group with an owner: who, and whether this account may remove people or hand it over (threads.ts). */
  ownership?: AboutOwnership;
  /** What this account may do to its members (capability 'moderate', moderation.ts). */
  moderation?: AboutModeration;
  /** Your own member label here (Signal); `configure` with key 'label' changes it. */
  label?: AboutLabel;
}

profile.output:
{
  /** As the network has them now. The adapter also emits an identity fact with these. */
  displayName?: string;
  handle?: string;
  avatar?: string;
  /** A banner picture (Discord). */
  banner?: string;
  /** A CSS colour for the banner when there is no picture (Discord's accent colour). */
  accent?: string;
  /** Bio or About text, as the network has it (Discord markdown, WhatsApp About, Signal About). */
  bio?: string;
  /** A short status line with an emoji (Discord custom status, Signal's About emoji). */
  status?: { text?: string; emoji?: string };
  pronouns?: string;
  /** ms epoch: when their account was made (Discord, from the id). */
  createdAt?: number;
  /** Your standing with them on this network. */
  relationship?: "friend" | "requested" | "requesting" | "blocked" | "contact" | "following" | "stranger";
  /** Spaces you share, native ids, with their name and roles there. All of them, not only where they posted. */
  mutualSpaces?: { id: string; nick?: string; roles?: { name: string; color?: string }[]; joinedAt?: number }[];
  /** Friends you share: native identity ids (identity facts for them are emitted first). */
  mutualFriends?: string[];
  /** When the person is you: your friends or contacts on this network, native identity ids. */
  friends?: string[];
  /** Connected accounts, websites, a phone number. */
  links?: { label: string; value: string; url?: string; verified?: boolean }[];
  /** Anything else worth a line: "Business account", "Local time". */
  facts?: { label: string; value: string }[];
  /** Badges the network shows on their profile, by name, with the network's picture. */
  badges?: { name: string; icon?: string }[];
  /** A frame drawn around their picture (Discord's avatar decoration). */
  decoration?: string;
  /** Their profile's own colours, as CSS hex, top first (Discord's theme colours). */
  themeColors?: string[];
  /** Your safety number with them (capability 'safetyNumbers'). */
  safety?: SafetyNumber;
  /** When the person is you: what the `setProfile` command can change on this account. Absent: only the bio. */
  editable?: ProfileField[];
  /** When the person is you: your username and its link, where the network has them and one is set. */
  username?: { name: string; link?: string };
  /** Their recent posts, newest first (X: up to 20 from their profile's Posts tab, reposts included, a pinned one first with `pinned`). Only in an answer to `profile`, never in a `personAbout` event. */
  posts?: PostFact[];
  /** Follower and following counts and their posts in all, where the network shows them. */
  counts?: { followers?: number; following?: number; posts?: number };
  /** They follow you (X). */
  followsYou?: boolean;
}

post.output:
{
  /** The post asked for. Absent on a page of more replies (`cursor` given) when the network leaves it out. */
  focal?: PostFact;
  /** What it answers, the thread's first post first, up to the one it replies to. */
  ancestors: PostFact[];
  /** The replies, in the network's order. Each is a short chain: a reply, then the answers under it the network shows with it (X: a conversation module, often its author continuing). The focal post's author continuing their own thread comes firs */
  replies: PostFact[][];
  /** Ask again with this `cursor` for more replies (X's "Show more replies"), or null when there are no more. */
  more: null | string;
}

postReactors.output:
{
  who: {
    id: string;
    followers?: number;
    following?: boolean;
    followsYou?: boolean;
    verified?: boolean;
  }[];
  /** Ask again with this cursor for more, or null. */
  more: null | string;
}

resolve.output:
{
  what: "space" | "person" | "group" | "channel" | "room";
  name: string;
  /** The network will not say more without acting (signal-cli has no group-link preview; Discord has no username lookup that does not send the request). `name` is then the pasted text, `actions` are still listed, and a note says why. A missing n */
  partial?: true;
  /** Native id of the space, conversation or identity, when the network says. */
  nativeId?: string;
  avatar?: string;
  description?: string;
  members?: number;
  online?: number;
  /** Already in it: native ids. */
  joined?: { space?: string; conversation?: string };
  relationship?: "friend" | "requested" | "requesting" | "blocked" | "contact" | "following" | "stranger";
  /** What this account can do with it now, best first. 'ask' = a join request the admins approve. */
  actions: AddAction[];
  /** ms epoch the invite runs out. */
  expires?: number;
  /** Native identity id of who made the invite (identity fact first). */
  inviter?: string;
  /** Plain notes: "Joining asks the admins first", "This server wants a verified phone". */
  notes?: string[];
}

appAutocomplete.input:
{
  conversation: string;
  query: string;
  command: string;
  app: string;
  options: AppOptionValue[];
  focused: string;
}

stickers.output:
{
  packs: StickerPackFact[];
  /** Pass as `cursor` for the next page; null at the end. */
  next: null | string;
  /** Why there are none, or a limit worth knowing ("Stickers from other servers need Nitro"). Shown in the picker. */
  note?: string;
}

send.input:
{
  conversation: string;
  body: string;
  replyTo?: string;
  attachments?: OutgoingAttachment[];
  /** capability 'linkPreviews' */
  preview?: LinkPreviewOut;
  /** A sticker from the `stickers` reply, by its id (capability 'sendStickers'); body may be empty with it. */
  sticker?: string;
  /** The files open once (capability 'sendViewOnce'). */
  viewOnce?: boolean;
  /** capability 'silentSend': nobody is notified of it (Discord's */
  silent?: boolean;
  /** capability 'replyMention', with replyTo: false, the reply does not ping its author. Absent: the network's default (it pings). */
  mentionReplied?: boolean;
}

publish.output:
{
  /** The network's id for the post (X: the tweet's rest id). */
  id: string;
  /** Where it opens on the network: https://x.com/<handle>/status/<id>. */
  url: string;
  /** ms epoch. */
  ts: number;
  author?: string;
  /** Plain text with links expanded, as the network shows it (X: a long post's whole text). */
  text: string;
  /** It answers this post (its id, and its author's native id where known). */
  replyTo?: { id: string; author?: string };
  repostOf?: PostFact;
  quoteOf?: PostFact;
  counts?: { replies?: number; reposts?: number; likes?: number; quotes?: number; views?: number };
  media?: PostMedia[];
  /** Pinned at the top of its author's profile. */
  pinned?: boolean;
  /** The thread it belongs to: the id of the thread's first post (X: conversation_id_str). */
  root?: string;
  /** What the account that read it has done to it (X: legacy.favorited, legacy.retweeted). */
  viewer?: PostViewer;
}

openDirect.output:
{
  /** Native id of the conversation. */
  conversation: string;
  /** It was there already, and nothing was created. */
  existed: boolean;
  /** Nothing exists on the network until the first message (Signal). */
  startsAtFirstSend?: boolean;
}

react.input:
{
  remove?: boolean;
  conversation: string;
  message: string;
  key: string;
  style?: "normal" | "super";
  emoji?: CustomEmojiFact;
}

call.input:
{
  input?: CallInput;
  call: string;
  conversation: string;
  op: "join";
  mode: CallMode;
  muted?: boolean;
  deafened?: boolean;
  ring?: boolean;
}
| { call: string; op: "leave" }
| { call: string; op: "mute"; muted: boolean; deafened: boolean }
| { call: string; op: "note" | "signal"; data: unknown }
| { call: string; op: "local"; muted?: boolean; user: string; volume?: number }
| { input: CallInput; call: string; op: "input" }
| { call: string; action: StageAction; op: "stage"; user?: string }
| { call: string; op: "sounds" }
| { call: string; op: "sound"; sound: string; guild: string }

