  muted?: boolean;
  /** A space's: */
  suppressEveryone?: boolean;
  /** A space's: role mentions do not notify there. */
  suppressRoles?: boolean;
}

add.output:
{
  /** What now exists on this account (native ids): open it. Space/conversation facts arrive before the reply. */
  space?: string;
  conversation?: string;
  identity?: string;
  relationship?: "friend" | "requested" | "requesting" | "blocked" | "contact" | "following" | "stranger";
  /** Asked; waiting on the other side (join request, friend request, follow request). */
  pending?: boolean;
  /** The network wants a check only the owner can do, in the account's live view. Nothing was done. */
  check?: "verify" | "rules" | "captcha" | "phone";
  /** Plain notes, shown after the action: "Joined; the admins must approve before you can post". */
  notes?: string[];
  /** The network wants the owner to confirm first (Discord: "You must confirm the friend request to add this user."): its words. Nothing was done. The page shows them with "Accept anyway" or "Add anyway", which sends the same command again with  */
  confirm?: string;
}

