addMembers.output:
{
  /** In it now. */
  added: string[];
  /** Invited: in once they accept (Matrix; Signal when it does not have their profile yet). */
  invited?: string[];
  /** Refused by the network, each with its sentence ("Their privacy settings don't let you add them"). */
  failed?: { id: string; reason: string }[];
  /** The About as it now stands. */
  about?: About;
}

createGroup.output:
{
  /** The new conversation. */
  conversation: string;
  /** In it now. */
  added: string[];
  /** Invited: in once they accept (Matrix; Signal when it does not have their profile yet). */
  invited?: string[];
  /** Refused by the network, each with its sentence. */
  failed?: { id: string; reason: string }[];
  /** Anything the owner should know ("Telegram made it a basic group"). */
  notes?: string[];
}

rsvp.output:
{
  nativeId: string;
  /** The space (a Discord guild) it belongs to. */
  space: string;
  name: string;
  description?: string;
  /** ms epoch. For a repeating event, its first occurrence (or the next, as the network keeps it). */
  start: number;
  end?: number;
  status: EventStatus;
  place?: { kind: "voice" | "stage"; conversation: string } | { kind: "external"; location: string };
  /** Its cover picture. */
  imageUrl?: string;
  /** How many said they are interested, when the network said. */
  interested?: number;
  /** This account said it is interested (the series). Absent: not known yet. */
  youInterested?: boolean;
  /** Native identity id of who made it (its identity fact comes first). */
  creator?: string;
  /** RFC 5545 rule without the "RRULE:" prefix ("FREQ=WEEKLY;INTERVAL=1;BYDAY=TU"); absent: once. Times are UTC. */
  rrule?: string;
  exceptions?: EventException[];
}

leave.input:
{
  target: AboutTarget;
  silent?: boolean;
  /** Native identity ids made admin as you leave (AboutLeaving.needsAdmin; Signal's `--admin`). */
  admins?: string[];
  /** Forget the group's data on this device too (AboutLeaving.canForget; Signal's `--delete`). */
  forget?: true;
}

answerGate.output:
{
  /** The gate is passed (rules, onboarding), or the application is in (apply: see status). */
  done: boolean;
  status?: "open" | "submitted" | "approved" | "rejected";
  /** What it asks next, when it asks more (onboarding after the rules). */
  next?: null | SpaceGate;
}

