defs.About:
/** What `about` answers, in native ids. */
type About = {
  /** The network's word for it: "Group", "Server", "Room", "Channel", "Community". */
  noun?: string;
  fields: AboutFields;
  members?: {
    list: AboutMember[];
    /** How many there are; list may hold fewer (Discord servers load members lazily). */
    total?: number;
    complete: boolean;
  };
  /** Adding people here, for an adapter with 'addMembers'. Left out where nobody adds people (DMs, servers, channels). */
  adding?: AboutAdding;
  roles?: AboutRole[];
  rules?: AboutRule[];
  /** This account's own standing here. */
  you?: { role?: string; rank?: number };
  invite?: AboutInvite;
  pinned?: AboutPinned;
  /** Read-only details only some networks have: "Room version", "Verification level", "Created". */
  facts?: { label: string; value: string }[];
  /** Leaving it (capability 'leave', servers.ts). */
  leaving?: AboutLeaving;
  /** Your own nickname here (capability 'nick', the `setNick` command): value null for none. */
  nick?: { value: null | string; canEdit: boolean; reason?: string; max?: number };
  /** You blocked this group: nothing from it reaches you (capability 'block'; the `block` command changes it). */
  blocked?: boolean;
  /** A thread's archiving, locking and following (threads.ts). */
  thread?: AboutThread;
  /** A group with an owner: who, and whether this account may remove people or hand it over (threads.ts). */
  ownership?: AboutOwnership;
  /** What this account may do to its members (capability 'moderate', moderation.ts). */
  moderation?: AboutModeration;
  /** Your own member label here (Signal); `configure` with key 'label' changes it. */
  label?: AboutLabel;
};

defs.AboutAdding:
/** Adding people to a group (capability 'addMembers', the `addMembers` command): whether this account may here, and */
type AboutAdding = {
  /** This account may add people here now. */
  can: boolean;
  /** Why not, in words. When it may, a limit worth knowing ("Only your friends", "Up to 10 people in all"). */
  reason?: string;
  who: AddWho;
  /** add: they are in at once. invite: they get an invite and are in once they accept (Matrix). */
  mode: "add" | "invite";
  /** How many more fit, when the network caps the group (Discord: 10 people in all). */
  room?: number;
};

defs.AboutChange:
/** One change. `invite` makes, replaces or turns off the invite link; `pin` pins or unpins a message. */
type AboutChange = { key: "history"; value: HistoryVisibility }
| { key: "addMembers"; value: Who }
| { key: "name"; value: string }
| { key: "topic"; value: string }
| { key: "avatar"; value: string }
| { key: "disappearing"; value: number }
| { key: "slowMode"; value: number }
| { key: "nsfw"; value: boolean }
| { key: "announceOnly"; value: boolean }
| { key: "editInfo"; value: Who }
| { key: "joinApproval"; value: boolean }
| { key: "joinRule"; value: JoinRule }
| { key: "encrypted"; value: boolean }
| { key: "autoArchive"; value: number }
| { key: "userLimit"; value: number }
| { key: "bitrate"; value: number }
| {
  key: "invite";
  op: "create" | "revoke";
  maxAge?: number;
  maxUses?: number;
  temporary?: boolean;
  code?: string;
}
| { key: "pin"; message: string; remove?: boolean; seconds?: null | number };

defs.AboutFields:
type AboutFields = {
  history?: AboutSetting;
  addMembers?: AboutSetting;
  name?: AboutSetting;
  topic?: AboutSetting;
  avatar?: AboutSetting;
  disappearing?: AboutSetting;
  slowMode?: AboutSetting;
  nsfw?: AboutSetting;
  announceOnly?: AboutSetting;
  editInfo?: AboutSetting;
  joinApproval?: AboutSetting;
  joinRule?: AboutSetting;
  encrypted?: AboutSetting;
  autoArchive?: AboutSetting;
  userLimit?: AboutSetting;
  bitrate?: AboutSetting;
};

defs.AboutInvite:
type AboutInvite = {
  /** The link, when there is one and this account may see it. */
  link: null | string;
  /** Make one, or a new one in place of the old (which stops working). */
  canCreate: boolean;
  /** Turn the link off. */
  canRevoke?: boolean;
  reason?: string;
  /** A Matrix address (alias) or room id, which works as a link without anyone making one. */
  derived?: boolean;
  /** Every link the account may see, newest first (capability 'inviteLinks'); `link` is then the newest of them. */
  links?: InviteLinkFact[];
  /** The space's own short address, which never runs out (Discord's vanity URL). */
  vanity?: string;
  /** The expiry and use limits a new link may have, and the defaults (capability 'inviteLinks'). */
  options?: InviteOptions;
};

defs.AboutLabel:
/** The member label you show in a group (Signal), About.label: a few words and an emoji. */
type AboutLabel = {
  value: null | string;
  emoji: null | string;
  canEdit: boolean;
  reason?: string;
  /** Characters. */
  max?: number;
};

defs.AboutLeaving:
/** Leaving a conversation or space, as this account may (About.leaving). */
type AboutLeaving = {
  can: boolean;
  /** Why not ("You own this server: give it to someone else in Discord first"), in words. */
  reason?: string;
  /** What happens, worth a line in the confirm ("You own this group: Discord makes someone else its owner"). */
  warning?: string;
  /** The network can leave without telling the others (Discord group DMs). */
  silent?: boolean;
  /** You are its only admin and others are in it: the network wants someone made admin as you leave (Signal's `quitGroup --admin`). The app asks whom, from its members, before leaving. */
  needsAdmin?: boolean;
  /** This device can also forget the group's data as it leaves (Signal's `--delete`), on a confirm of its own. */
  canForget?: boolean;
};

defs.AboutMember:
type AboutMember = {
  /** Native identity id. The adapter emits identity facts for members first. */
  id: string;
  /** What the network calls their standing: "Admin", "Owner", "Moderator", the top Discord role. */
  role?: string;
  /** Power, to sort by: 100 for admins and owners, 50 for moderators, 0 for members. Matrix: the power level. */
  rank?: number;
  /** CSS colour of their role (Discord). */
  color?: string;
  /** Their member label in a group (Signal), a few words and an emoji. */
  label?: { text?: string; emoji?: string };
  /** How this account stands to them, for moderating (capability 'moderate', moderation.ts). */
  mod?: MemberMod;
};

defs.AboutModeration:
/** What this account may do to the members of a group or server (About.moderation). Absent: nothing it may do. */
type AboutModeration = {
  /** Take someone out (Signal: remove from the group; Discord: kick). They can come back with an invite. */
  remove?: ModPower;
  /** Ban them: out, and they cannot come back. `deleteHistory`: the choices of their recent messages to delete with the ban, seconds (Discord's dialog). */
  ban?: { can: boolean; reason?: string; deleteHistory?: number[] };
  /** Make someone an admin or stop them being one (Signal). */
  admins?: ModPower;
  /** Give or take a role (Discord): the ones this account may hand out, below its own top role, by AboutRole id. */
  roles?: { can: boolean; reason?: string; assignable: string[] };
  /** Time someone out (Discord): they cannot send, react, talk or join voice until it ends. The client's own choices, seconds. */
  timeout?: { can: boolean; reason?: string; durations: number[] };
  /** End the group for everyone (Signal): nobody can send or change anything in it again. */
  end?: ModPower;
  /** Server mute or unmute someone in voice (Discord: Mute Members, in the voice channel). */
  voiceMute?: ModPower;
  /** Server deafen or undeafen someone in voice (Discord: Deafen Members). */
  voiceDeafen?: ModPower;
  /** Move someone in voice to another voice channel, or disconnect them (Discord: Move Members). */
  voiceMove?: ModPower;
  /** Who is banned, as native identity ids, when the network lists them without being asked (Signal). */
  banned?: string[];
  /** The banned list is read on a click, through the `bans` command (Discord). */
  bansOnRequest?: boolean;
  /** People asking to join, native identity ids; they are answered under Requests (kind 'join'). */
  requesting?: string[];
  /** What moderating here is left to the network's own app, in words ("Audit log, AutoMod, …: open Discord"). */
  elsewhere?: string;
};

defs.AboutOwnership:
/** A group someone owns, as this account stands in it (About.ownership): who owns it, and what this account may do. */
type AboutOwnership = {
  /** Native identity id of the owner, when the network names one (in an AboutView: its hub identity id). */
  owner?: string;
  youOwn: boolean;
  /** This account may take people out of it (removeMember). */
  canRemove: boolean;
  /** This account may give it to someone else in it (setOwner). */
  canTransfer: boolean;
  /** Why not, in words. */
  reason?: string;
};

defs.AboutPinned:
type AboutPinned = {
  /** Native message ids, newest pin first. */
  messages: string[];
  canEdit: boolean;
  reason?: string;
  /** The network's whole list, just read (Discord's pinned list). Absent: the network keeps none this account can read (Signal), so the hub adds the pins it saw itself. */
  complete?: boolean;
};

defs.AboutRole:
type AboutRole = {
  id: string;
  name: string;
  color?: string;
  rank: number;
  /** Members with it, when known. */
  count?: number;
};

defs.AboutRule:
/** "Who can do what", in words: one row per thing the network gates. */
type AboutRule = {
  what: string;
  who: string;
  /** This account may. */
  you: boolean;
};

defs.AboutSetting:
/** One setting: its value, and whether this account may change it. */
type AboutSetting<K extends AboutKey = AboutKey> = {
  /** null: the network has it but did not say. */
  value: null | import("@dither-chat/protocol").AboutValues[K];
  canEdit: boolean;
  /** Why not, in words (shown on hover and under the setting). Also a limit worth knowing when canEdit is true. */
  reason?: string;
  /** The values this account may pick here, where they depend on the place (Discord's bitrate by the server's boosts). */
  options?: number[];
  /** Only the change can be sent, not the value read back (Signal's join approval: signal-cli does not say whether it is on). The panel offers it as a choice, with the reason saying why the current value is unknown. */
  writeOnly?: boolean;
};

defs.AboutThread:
/** A thread's own part of its About: archiving, locking and following, and whether this account may. */
type AboutThread = {
  archived: boolean;
  locked: boolean;
  /** This account may archive and unarchive it (who started it, or a moderator; a locked one only a moderator). */
  canArchive: boolean;
  /** This account may lock and unlock it (a moderator). */
  canLock: boolean;
  /** Why not, in words. */
  reason?: string;
  /** This account follows it. */
  joined: boolean;
  notify?: "all" | "mentions" | "none";
  muted?: boolean;
  mutedUntil?: number;
};

defs.AccountNotice:
/** Something the network wants the owner to do on the account, as it says it: verify a phone or email, agree to new */
type AccountNotice = {
  /** Stable while the network says the same thing: 'required:REQUIRE_VERIFIED_PHONE', 'standing'. */
  key: string;
  kind: "verify" | "agreements" | "standing" | "age" | "other";
  /** A few words: "Verify your phone number". */
  title: string;
  /** A plain sentence of what it means and where to do it. */
  message: string;
  /** The account's live view is where to do it. */
  liveView?: boolean;
  /** ms epoch, when the network said it first, where it says. */
  since?: number;
};

defs.AccountSession:
/** One place the account is signed in. */
type AccountSession = {
  /** The network's id for it (Discord's id_hash). */
  id: string;
  /** The session dither runs (its sandbox). */
  current?: boolean;
  /** "Chrome", "Discord Android". */
  client?: string;
  os?: string;
  /** Rough place, as the network guesses it. */
  location?: string;
  /** ms epoch. */
  lastUsed?: number;
};

defs.AddRef:
/** What a pasted or typed thing could be. parseAdd gives every reading; the hub asks a fitting account to resolve one. */
type AddRef = { kind: "invite"; network: Network; code: string; url: string }
| { kind: "place"; network: Network; address: string; via?: string[] }
| { kind: "name"; network: Network; name: string }
| { kind: "person"; network: Network; handle: string };

defs.AppCommandFact:
type AppCommandFact = {
  /** The network's id for it (Discord: the command's id, then its group and subcommand names, NUL-separated). */
  id: string;
  /** What is typed after the slash, groups and subcommands included: "remind me". */
  name: string;
  description?: string;
  /** The app's id (AppFact.id). */
  app: string;
  kind: AppCommandKind;
  options: AppOptionFact[];
  /** Only for age-restricted channels. */
  nsfw?: true;
};

defs.AppFact:
type AppFact = {
  id: string;
  name: string;
  icon?: string;
  /** The app's bot, as a native identity id (its identity fact comes first). */
  bot?: string;
};

defs.AppModalFact:
/** A form a bot opened in answer to one of the owner's interactions. It can be sent once, within 15 minutes. */
type AppModalFact = {
  /** The network's id for it (Discord: the interaction id it answers to). */
  id: string;
  /** The interaction it answers (InteractResult.nonce). */
  nonce: string;
  conversation: string;
  app: AppFact;
  title: string;
  fields: ModalFieldFact[];
};

defs.AppOptionFact:
type AppOptionFact = {
  name: string;
  description?: string;
  type: AppOptionType;
  required?: true;
  /** The only values it takes, when the app lists them. */
  choices?: AppChoiceFact[];
  /** The app suggests values as you type (`appAutocomplete`). */
  autocomplete?: true;
  /** For numbers: the smallest and largest it takes. */
  min?: number;
  max?: number;
  /** For strings: the shortest and longest. */
  minLength?: number;
  maxLength?: number;
};

defs.AttachmentFact:
type AttachmentFact = {
  nativeId?: string;
  kind: AttachmentKind;
  mime?: string;
  name?: string;
  size?: number;
  width?: number;
  height?: number;
  url: string;
  /** Its description (alt text), shown with it and searched (docs/rich-messages.md). */
  alt?: string;
  /** Marked as a spoiler: drawn blurred until clicked. */
  spoiler?: boolean;
  /** The network flagged it as explicit: drawn blurred until clicked, as a spoiler. */
  explicit?: boolean;
  /** A voice message (rich.ts VoiceFact): drawn as a player with its waveform. */
  voice?: VoiceFact;
};

defs.CallEffect:
/** A sound someone played or an emoji they sent in the call you are in (Discord's soundboard and voice effects). */
type CallEffect = {
  /** Who: a native user id from the adapter, a hub identity id from the hub. */
  who: string;
  /** A Unicode emoji, or a custom emoji's name. */
  emoji?: string;
  /** A custom emoji's picture. */
  emojiUrl?: string;
  sound?: { id: string; name: string };
};

defs.CallFact:
/** A call as the network says it stands: ringing, going on, or over (the adapter's `callState` event). Idempotent: the */
type CallFact = {
  /** The call's own id on the network: Discord the id of its call message, Signal the call id. */
  nativeId: string;
  conversation: string;
  /** Who started it, when known. */
  caller?: string;
  /** ms epoch: when it started, the network's own time. A call that rang long ago never alerts (call.ts RING). */
  startedAt: number;
  state: "ringing" | "ongoing" | "ended";
  /** It is ringing this account now. */
  ringsSelf?: boolean;
  /** This account started it. */
  outgoing?: boolean;
  video?: boolean;
  /** Native identity ids of everyone who was in it, as far as the network says. */
  participants?: string[];
  /** With state 'ended'. */
  outcome?: "cancelled" | "answered" | "elsewhere" | "missed" | "declined" | "busy";
  /** ms epoch it ended, when known; with startedAt it gives the duration. */
  endedAt?: number;
  /** ms epoch someone answered, when known (a duration counts from here when it is). */
  answeredAt?: number;
  /** Native id of its line in the timeline (Discord's call message, Signal's offer). */
  message?: string;
};

defs.CallInput:
/** How this device's microphone is handled (Settings → Calls, kept per device). In bridge mode the account's client is */
type CallInput = {
  /** The browser's noise suppression on the microphone (and the account client's own, in bridge mode). */
  noiseSuppression: boolean;
  /** When the microphone counts as speaking: 'auto' (the network's or the device's own judgement), or a level in dB from -100 (everything) to 0. */
  sensitivity: number | "auto";
};

defs.CallParticipant:
type CallParticipant = {
  /** Native user id. */
  id: string;
  muted: boolean;
  deafened: boolean;
  speaking: boolean;
  /** Camera on. */
  video?: boolean;
  /** Sharing their screen (Go Live). */
  streaming?: boolean;
  /** Muted or deafened by a moderator (a server mute), rather than by themselves. */
  serverMuted?: boolean;
  serverDeafened?: boolean;
  /** How loud they are for this account only, percent: 100 as they are, 0 to VOLUME_MAX (the network's per-person volume). Absent: 100. */
  volume?: number;
  /** Muted for this account only. */
  localMute?: boolean;
  /** On a stage: what they are there (StageRole). Absent outside a stage. */
  stage?: "invited" | "audience" | "speaker" | "hand";
};

defs.CallStage:
/** A stage call's own facts (CallState.stage). */
type CallStage = {
  /** What the stage is about, when someone started it with a topic. */
  topic: null | string;
  /** This account may invite people to speak and move speakers back to the audience (Discord: Mute Members there). */
  moderator: boolean;
};

defs.CallState:
type CallState = {
  conversation: string;
  participants: CallParticipant[];
  /** Present when the call is a stage. */
  stage?: CallStage;
};

defs.ConversationFact:
type ConversationFact = {
  /** Discord channel snowflake | Matrix room id | Matrix thread "<roomId>|<rootEventId>" | Signal group "group:<base64 id>" | Signal 1:1 "dm:<selfAci>:<peerAci>" */
  nativeId: string;
  shape: Shape;
  variant?: "text" | "voice" | "stage" | "rules" | "media" | "posts" | "announcement" | "forum" | "feed";
  /** Omit for directs: the UI names them after the peer. */
  name?: string;
  topic?: string;
  avatarUrl?: string;
  encrypted?: boolean;
  archived?: boolean;
  /** Threads: the conversation they hang off. */
  parentConversation?: string;
  /** Containing spaces (a graph: a Matrix room may be in several). */
  spaces?: SpaceRef[];
  /** Identity native IDs. Only for direct, group and self; big channels skip this. */
  participants?: string[];
  mute?: NativeMute;
  lastMessageAt?: number;
  /** A thread's own facts: whether you follow it, its tags, who started it (threads.ts). */
  thread?: ThreadFact;
  /** A forum or media channel's tags and default order (threads.ts). */
  forum?: ForumFact;
};

defs.EventException:
/** One occurrence of a repeating event that differs from the rule: moved, or called off. */
type EventException = {
  /** The network's id for the change (Discord: a snowflake of the occurrence's original start). */
  nativeId: string;
  /** ms epoch: when this occurrence would have started by the rule (the calendar's RECURRENCE-ID). */
  original: number;
  /** Moved to, when moved. */
  start?: number;
  end?: number;
  cancelled?: boolean;
  /** This account's own answer to this occurrence, when it differs from the series'. */
  youInterested?: boolean;
};

defs.ForumFact:
/** What a forum (or media) channel says of its posts (ConversationFact.forum). */
type ForumFact = {
  tags: ForumTag[];
  /** The order its own client shows posts in by default: latest activity or newest first. */
  sort?: "activity" | "created";
  /** How its own client lays posts out by default. */
  layout?: "list" | "gallery";
  /** A new post must carry at least one tag (Discord's REQUIRE_TAG). */
  tagRequired?: boolean;
};

defs.ForumTag:
/** One tag a forum offers its posts (Discord's forum tags). */
type ForumTag = {
  id: string;
  name: string;
  /** A unicode emoji, or a custom one's name. */
  emoji?: string;
  /** Only moderators may put it on a post. */
  moderated?: boolean;
};

defs.ForwardFact:
/** Where a forwarded message came from, as far as the network says. Discord names the channel, message and */
type ForwardFact = {
  conversation?: string;
  message?: string;
  /** The original's community, when the conversation alone does not say (a Discord guild id). */
  space?: string;
  author?: string;
  authorName?: string;
  ts?: number;
};

defs.GateAnswer:
/** The owner's answer to a gate. agree: they read and agree to the rules. answers: by question id. picks: option ids. */
type GateAnswer = {
  kind: "rules" | "apply" | "onboarding";
  agree?: boolean;
  answers?: Record<string, string | number>;
  picks?: string[];
};

defs.GatePrompt:
/** One onboarding question: pick channels or roles. */
type GatePrompt = {
  id: string;
  title: string;
  /** Only one option may be picked. */
  single: boolean;
  required: boolean;
  options: { id: string; title: string; description?: string; emoji?: string }[];
};

defs.GateQuestion:
/** A question an application asks (Discord's membership screening form). */
type GateQuestion = {
  /** Its place in the form, as a string ("0", "1", ...). */
  id: string;
  kind: "text" | "paragraph" | "choice";
  label: string;
  description?: string;
  required: boolean;
  choices?: string[];
};

defs.IdentityFact:
type IdentityFact = {
  nativeId: string;
  handle?: string;
  displayName?: string;
  avatarUrl?: string;
  isBot?: boolean;
  isSelf?: boolean;
  /** In the address book / friends list. Contacts get a Person, strangers in big channels do not. */
  contact?: boolean;
  /** Your private nickname for them as the network keeps it (Signal's nickname, capability 'contactNotes'); '' when none. Left out when the adapter did not read it. `displayName` is then their own or address-book name, without it. */
  nickname?: string;
  /** Your private note about them as the network keeps it (Signal's contact note, capability 'contactNotes'); '' when none. */
  note?: string;
};

defs.InteractionOutcome:
type InteractionOutcome = {
  nonce: string;
  conversation: string;
  /** The message whose control was pressed. */
  message?: string;
  state: InteractionState;
  /** Why, for failed, in words. */
  error?: string;
};

defs.InteractRequest:
/** What one `interact` does. */
type InteractRequest = { kind: "component"; message: string; component: string; values?: string[] }
| {
  kind: "command";
  command: string;
  app: string;
  options: AppOptionValue[];
  target?: { kind: "message" | "user"; id: string };
}
| { kind: "modal"; modal: string; values: ModalValue[] };

defs.InviteLinkFact:
/** One invite link, as the network lists it. */
type InviteLinkFact = {
  code: string;
  url: string;
  /** Native conversation id it leads to. */
  conversation?: string;
  /** Native identity id of who made it. */
  inviter?: string;
  uses?: number;
  /** 0: no limit. */
  maxUses?: number;
  /** ms epoch; absent: never. */
  expiresAt?: number;
  /** Members who join with it are removed when they go offline, unless given a role (Discord). */
  temporary?: boolean;
  /** This account may turn it off. */
  canRevoke?: boolean;
};

defs.InviteOptions:
/** The choices the network's own invite dialog offers, and its defaults (Discord: 7 days, no limit). */
type InviteOptions = {
  /** Seconds; 0: never. */
  maxAge: number[];
  /** 0: no limit. */
  maxUses: number[];
  defaults: { maxAge: number; maxUses: number };
};

defs.LinkPreviewOut:
/** A link preview to send with a message (the `send` command's `preview`, capability 'linkPreviews'): the hub fetched */
type LinkPreviewOut = {
  url: string;
  title: string;
  description?: string;
  /** A picture for it, a file in the hub's spool; the adapter reads it during the send and the hub deletes it after. */
  image?: string;
};

defs.MemberFact:
/** Someone seen as a member of a space. The identity fact for `who` is emitted first. */
type MemberFact = {
  /** Native identity id. */
  who: string;
  /** ms epoch: when they joined the space, where the network says. */
  joinedAt?: number;
  /** Role names in the space. */
  roles?: string[];
  /** Their nickname in the space. */
  nick?: string;
};

defs.MemberMod:
/** How this account stands to one member, where it differs from the About's powers (AboutMember.mod). */
type MemberMod = {
  /** This account cannot act on them: they outrank it, own the place, or are this account. */
  above?: boolean;
  reason?: string;
  /** Their roles by AboutRole id (Discord), to give or take one. */
  roles?: string[];
  /** ms epoch: timed out until then (Discord). */
  timedOutUntil?: number;
};

defs.MentionablePerson:
type MentionablePerson = {
  /** Native identity id, as `<@nativeId>` in a body. */
  nativeId: string;
  name: string;
  handle?: string;
  avatar?: string;
  isBot?: boolean;
  /** ms of their last message in this conversation, when the adapter knows it. */
  lastSpoke?: number;
};

defs.MentionableRole:
/** A role that may be pinged here (Discord: a mentionable role, or any role while you have Mention Everyone). */
type MentionableRole = {
  id: string;
  name: string;
  /** #RRGGBB */
  color?: string;
  count?: number;
};

defs.MessageFact:
/** Canonical message body: a Discord-flavoured Markdown subset. */
type MessageFact = {
  /** Discord snowflake | Matrix event id | Signal "<authorAci>:<sentTimestamp>" */
  nativeId: string;
  conversation: string;
  author: string;
  ts: number;
  editedTs?: number;
  kind?: "call" | "sticker" | "text" | "encrypted" | "media" | "system";
  body: string;
  replyTo?: string;
  /** This message is the root of that thread conversation. */
  threadRoot?: string;
  mentionsSelf?: boolean;
  /** With mentionsSelf: the mention was */
  mentionsAll?: boolean;
  attachments?: AttachmentFact[];
  /** Full reaction snapshot (backfill). Live changes use the `reaction` event. */
  reactions?: ReactionFact[];
  /** This message forwards another, as the network marks it. body and attachments are the forwarded content. */
  forward?: ForwardFact;
  /** Its sender sent it silently (Discord's */
  silent?: boolean;
  /** Embeds as `embeds` (api.ts EmbedView), and the keys of rich.ts RichExtra. */
  extra?: Record<string, unknown>;
};

defs.MessageModeration:
/** What this account may do to others' messages here (ReactionContext.moderation). */
type MessageModeration = {
  /** Delete someone else's message for everyone (Discord: Manage Messages; Signal: a group admin's delete). */
  delete: boolean;
  /** Remove others' reactions: all, one emoji's, one person's (Discord: Manage Messages). */
  reactions?: boolean;
};

defs.ModAction:
/** One moderating action. `who`: a native identity id (the hub's API takes hub identity ids instead). */
type ModAction = { op: "remove"; who: string }
| { op: "ban"; who: string; deleteSeconds?: number }
| { op: "unban"; who: string }
| { op: "admin"; who: string; remove?: true }
| { op: "role"; who: string; role: string; remove?: true }
| { op: "timeout"; who: string; seconds: number }
| { op: "end" }
| { op: "voiceMute"; who: string; on: boolean }
| { op: "voiceDeafen"; who: string; on: boolean }
| { op: "move"; who: string; to: string }
| { op: "disconnect"; who: string };

defs.ModalFieldFact:
/** A field of a form. Its `id` is the bot's custom id. */
type ModalFieldFact = {
  kind: "text";
  id: string;
  label?: string;
  description?: string;
  style: "paragraph" | "short";
  placeholder?: string;
  value?: string;
  required?: true;
  minLength?: number;
  maxLength?: number;
}
| {
  kind: "select";
  id: string;
  label?: string;
  description?: string;
  select: SelectKind;
  options?: SelectOptionFact[];
  placeholder?: string;
  min?: number;
  max?: number;
  required?: true;
}
| {
  kind: "radio";
  id: string;
  label?: string;
  description?: string;
  options: SelectOptionFact[];
  required?: true;
}
| {
  kind: "checkboxes";
  id: string;
  label?: string;
  description?: string;
  options: SelectOptionFact[];
  min?: number;
  max?: number;
  required?: true;
}
| { kind: "checkbox"; id: string; label?: string; description?: string; default?: true }
| { kind: "file"; id: string; label?: string; description?: string; required?: true }
| { kind: "display"; text: string };

defs.ModalValue:
/** An answer to one field of a form (AppModalFact). Only what its kind takes. */
type ModalValue = {
  /** The field's id (ModalFieldFact id). */
  field: string;
  /** A text field's text, or a radio group's value. */
  value?: string;
  /** A select's or checkbox group's values (native ids for user, role and channel selects). */
  values?: string[];
  /** A lone checkbox. */
  checked?: boolean;
};

defs.NativeMute:
/** The network's own notification setting for a place. An empty object says nothing is set there: an adapter sends */
type NativeMute = {
  level?: "all" | "mentions" | "none";
  /** ms epoch; muted until then. */
  until?: number;
  /** Muted outright (Discord's Mute), rather than set to notify on nothing. */
  muted?: boolean;
  /** A space's: */
  suppressEveryone?: boolean;
  /** A space's: role mentions do not notify there. */
  suppressRoles?: boolean;
};

defs.NativeScheduledFact:
/** A message scheduled with the network's own Send later (Discord's scheduled messages), native ids. */
type NativeScheduledFact = {
  nativeId: string;
  conversation: string;
  body: string;
  /** ms epoch it goes out at. */
  dueAt: number;
  silent?: boolean;
  /** Native message id it replies to. */
  replyTo?: string;
};

defs.NetworkFolder:
/** A folder of spaces as the network keeps your arrangement (Discord's server folders). */
type NetworkFolder = {
  id?: string;
  name?: string;
  /** CSS colour. */
  color?: string;
  /** Native space ids, in the network's order. A lone space outside any folder is a folder of one without a name. */
  spaces: string[];
};

defs.NetworkQuery:
/** What a network search asks for, from the hub's query language (search.ts) in the network's terms. */
type NetworkQuery = {
  /** Words and phrases as typed ("quoted" kept), without operators. */
  text: string;
  /** Native identity ids. */
  authors?: string[];
  mentions?: string[];
  /** Native conversation ids, inside a space scope. */
  in?: string[];
  has?: string[];
  /** ms, inclusive and exclusive as search.ts. */
  after?: number;
  before?: number;
  sort?: "newest" | "oldest" | "relevance";
};

defs.OutgoingAttachment:
/** A file to send, in the hub's spool. The adapter reads it during the send; the hub deletes it afterwards. */
type OutgoingAttachment = {
  path: string;
  name: string;
  mime: string;
  size: number;
  kind: AttachmentKind;
  /** Send it as the network's voice message (capability 'sendVoice', media.ts): the only file of its send. */
  voice?: VoiceOut;
};

defs.OwnPresence:
type OwnPresence = {
  state: OwnPresenceState;
  /** ms epoch the state goes back to online by itself (Discord's "for 1 hour"). */
  until?: number;
  status?: OwnStatus;
};

defs.OwnStatus:
/** Your own status line. Absent fields: none. */
type OwnStatus = {
  text?: string;
  /** A Unicode emoji, or a custom one as `:name:` (it shows by name). */
  emoji?: string;
  /** ms epoch it clears itself at. */
  expiresAt?: number;
};

defs.PersonAbout:
/** What a network says about one person (the `profile` command, docs/profile.md), in native ids. Only what the */
type PersonAbout = {
  /** As the network has them now. The adapter also emits an identity fact with these. */
  displayName?: string;
  handle?: string;
  avatar?: string;
  /** A banner picture (Discord). */
  banner?: string;
  /** A CSS colour for the banner when there is no picture (Discord's accent colour). */
  accent?: string;
  /** Bio or About text, as the network has it (Discord markdown, WhatsApp About, Signal About). */
  bio?: string;
  /** A short status line with an emoji (Discord custom status, Signal's About emoji). */
  status?: { text?: string; emoji?: string };
  pronouns?: string;
  /** ms epoch: when their account was made (Discord, from the id). */
  createdAt?: number;
  /** Your standing with them on this network. */
  relationship?: "friend" | "requested" | "requesting" | "blocked" | "contact" | "following" | "stranger";
  /** Spaces you share, native ids, with their name and roles there. All of them, not only where they posted. */
  mutualSpaces?: { id: string; nick?: string; roles?: { name: string; color?: string }[]; joinedAt?: number }[];
  /** Friends you share: native identity ids (identity facts for them are emitted first). */
  mutualFriends?: string[];
  /** When the person is you: your friends or contacts on this network, native identity ids. */
  friends?: string[];
  /** Connected accounts, websites, a phone number. */
  links?: { label: string; value: string; url?: string; verified?: boolean }[];
  /** Anything else worth a line: "Business account", "Local time". */
  facts?: { label: string; value: string }[];
  /** Badges the network shows on their profile, by name, with the network's picture. */
  badges?: { name: string; icon?: string }[];
  /** A frame drawn around their picture (Discord's avatar decoration). */
  decoration?: string;
  /** Their profile's own colours, as CSS hex, top first (Discord's theme colours). */
  themeColors?: string[];
  /** Your safety number with them (capability 'safetyNumbers'). */
  safety?: SafetyNumber;
  /** When the person is you: what the `setProfile` command can change on this account. Absent: only the bio. */
  editable?: ProfileField[];
  /** When the person is you: your username and its link, where the network has them and one is set. */
  username?: { name: string; link?: string };
  /** Their recent posts, newest first (X: up to 20 from their profile's Posts tab, reposts included, a pinned one first with `pinned`). Only in an answer to `profile`, never in a `personAbout` event. */
  posts?: PostFact[];
  /** Follower and following counts and their posts in all, where the network shows them. */
  counts?: { followers?: number; following?: number; posts?: number };
  /** They follow you (X). */
  followsYou?: boolean;
};

defs.PostFact:
/** One post as the network shows it. `author` is a native identity id (an identity fact for it comes first). A */
type PostFact = {
  /** The network's id for the post (X: the tweet's rest id). */
  id: string;
  /** Where it opens on the network: https://x.com/<handle>/status/<id>. */
  url: string;
  /** ms epoch. */
  ts: number;
  author?: string;
  /** Plain text with links expanded, as the network shows it (X: a long post's whole text). */
  text: string;
  /** It answers this post (its id, and its author's native id where known). */
  replyTo?: { id: string; author?: string };
  repostOf?: PostFact;
  quoteOf?: PostFact;
  counts?: { replies?: number; reposts?: number; likes?: number; quotes?: number; views?: number };
  media?: PostMedia[];
  /** Pinned at the top of its author's profile. */
  pinned?: boolean;
  /** The thread it belongs to: the id of the thread's first post (X: conversation_id_str). */
  root?: string;
  /** What the account that read it has done to it (X: legacy.favorited, legacy.retweeted). */
  viewer?: PostViewer;
};

defs.ProfileChange:
/** What the `setProfile` command changes: only the fields given (see it there). */
type ProfileChange = {
  bio?: string;
  name?: string;
