  paymentMethodName: string;
  /** Yours only: the payment account it was posted with. */
  paymentAccountId: null | string;
  securityDepositPct: number;
  mine: boolean;
  state: string;
  activated: boolean;
  private: boolean;
  /** The maker's own words. */
  extraInfo: null | string;
  countries: string[];
  at: number;
};

defs.ExchangePaymentAccount:
type ExchangePaymentAccount = {
  id: string;
  name: string;
  /** The payment method's id: ZELLE, SEPA, PAYPAL, BLOCK_CHAINS… */
  method: string;
  currencies: string[];
  /** The selected currency, when the account has one. */
  currency: null | string;
  at: null | number;
};

defs.ExchangeTrade:
type ExchangeTrade = {
  id: string;
  shortId: string;
  at: number;
  /** In the node's words: "XMR buyer as taker"… */
  role: string;
  offer: ExchangeOffer;
  amount: string;
  price: string;
  volume: string;
  state: string;
  phase: string;
  payoutState: string;
  disputeState: string;
  depositsUnlocked: boolean;
  paymentSent: boolean;
  paymentReceived: boolean;
  payoutPublished: boolean;
  payoutUnlocked: boolean;
  completed: boolean;
  /** When the trade period ends, or null. */
  deadline: null | number;
  /** The peer's node address (an onion), the way the node names it. */
  peer: null | string;
};

privacy.session.output:
{
  /** The app is open on a page that is not a sign-in page. */
  signedIn: boolean;
  /** The tab's page, origin and path only. */
  page: null | string;
  passkey: PrivacyPasskey;
}

defs.PrivacyPasskey:
type PrivacyPasskey = {
  enrolled: boolean;
  /** How many passkeys the account holds (one, normally). */
  count: number;
  /** The first 8 characters of the newest one's credential id (base64url). */
  credentialIdPrefix: null | string;
  algorithm: null | string;
  rpId: null | string;
  createdAt: null | number;
  lastUsedAt: null | number;
  /** When a sign-in with it was seen to finish. */
  signInCheckedAt: null | number;
};

events.statements.pulled:
{
  ok: boolean;
  /** Files it added to the spool. */
  saved: number;
  skipped?: "signed-out" | "unchanged";
  /** What it needs from you (a new access URL, a sign-in), or why it failed. */
  needs?: string;
}

defs.StatementAccount:
/** An account at the source: names only, never a balance. */
type StatementAccount = {
  id: string;
  name: string;
  /** The bank or service it is at. */
  institution: null | string;
  currency: null | string;
  kind: "unknown" | "bank" | "brokerage" | "card" | "wallet" | "payments" | "orders";
};

defs.StatementFile:
/** One pulled file. */
type StatementFile = {
  /** A per-account counter: the cursor. A later file has a higher seq. */
  seq: number;
  id: string;
  /** What the app saves it as, in `dir` ("" for the top of its raw folder): "simplefin-20261109T061317-w0.json". */
  name: string;
  dir: string;
  mime: string;
  size: number;
  /** Hex, of the file's bytes. */
  sha256: string;
  pulledAt: number;
  /** The span the source was asked for, when it was asked for one. */
  coverage?: { from: number; to: number };
};

defs.DnsRecord:
type DnsRecord = {
  /** The host's id for it: what dns.edit and dns.remove take. */
  id: string;
  /** Relative to the zone: `@`, `www`, `_acme-challenge.tn`. */
  name: string;
  type: string;
  content: string;
  /** Seconds. */
  ttl: null | number;
  /** MX and SRV priority. */
  prio?: null | number;
};

defs.DnsZone:
type DnsZone = {
  /** The domain, example.com */
  name: string;
  /** The host's word for it (active, expired…), when it says. */
  status: null | string;
  /** When the registration runs out (ISO 8601), when the host says. */
  expiry: null | string;
};

claude.session.output:
{
  /** null until the extractor has looked. */
  signedIn: null | boolean;
  /** The email claude.ai says is signed in. */
  email: null | string;
  /** The email this account is for (its config). */
  expectedEmail: null | string;
  /** The tab's page, origin and path only. */
  page: null | string;
  /** The organizations' rate limit tiers claude.ai reports (`default_claude_max_20x`), when signed in. */
  tiers: string[];
}

claude.survey.output:
{
  page: string;
  title: string;
  headings: string[];
  inputs: {
    type: string;
    name: null | string;
    id: null | string;
    placeholder: null | string;
    label: null | string;
  }[];
  buttons: string[];
  challenge: boolean;
}
